H0, W0 = len(grid0), len(grid0[0])
markers0 = [(r,c) for r in range(H0) for c in range(W0) if grid0[r][c] == 8]
output0 = data[0]['output']

print(f"Demo 0: shape {H0}x{W0} → {len(output0)}x{len(output0[0])}")
print(f"Markers: {markers0}")

# If output is 4x3 and markers are at (row, col):
# Row bandwidth = H0 / len(output0) = 23/4 ≈ 5-6 rows per band
# Col bandwidth = W0 / len(output0[0]) = 8/3 ≈ 2-3 cols per band

print(f"\nOutput shape: {len(output0)} x {len(output0[0])}")

# Row bands might be: 0-4, 6-15, 17-22 or similar
# Let's find which row band each marker is in (with separator rows 5, 11, 17)
sep_rows = [5, 11, 17]  # from earlier analysis
print(f"\nWith row separators at {sep_rows}:")
for pr in range(len(output0)):
    if pr == 0:
        rmin, rmax = 0, sep_rows[0]-1
    elif pr == 1:
        rmin, rmax = sep_rows[0]+1, sep_rows[1]-1
