        cmin, cmax = 0, sep_cols[0]-1
    elif pc == 1:
        cmin, cmax = sep_cols[0]+1, sep_cols[1]-1
    else:
        cmin, cmax = sep_cols[1]+1, W0-1
    band_markers = [p for p in markers0 if cmin <= p[1] <= cmax]
    print(f"  Col band {pc} (cols {cmin}-{cmax}): {len(band_markers)} markers")

# Find panel (pr, pc) that has markers
