    for pc in range(len(output0[0])):
        for p in markers0:
            # Check if marker is in this panel
            in_pr = False
            in_pc = False
            if pr == 0:
                rmin, rmax = 0, sep_rows[0]-1
            elif pr == 1:
                rmin, rmax = sep_rows[0]+1, sep_rows[1]-1
            elif pr == 2:
                rmin, rmax = sep_rows[1]+1, sep_rows[2]-1
            else:
                rmin, rmax = sep_rows[2]+1, H0-1
            if rmin <= p[0] <= rmax:
                in_pr = True
            if pc == 0:
                cmin, cmax = 0, sep_cols[0]-1
            elif pc == 1:
                cmin, cmax = sep_cols[0]+1, sep_cols[1]-1
            else:
                cmin, cmax = sep_cols[1]+1, W0-1
            if cmin <= p[1] <= cmax:
                in_pc = True
            if in_pr and in_pc:
                panel_counts[(pr, pc)] = panel_counts.get((pr, pc), 0) + 1
                print(f"  Panel ({pr},{pc}): marker at {p}")

print(f"\nPanel counts: {panel_counts}")
print(f"Output: {output0}")

